s64 q32_mul_c(s64 a, s64 b){
  int neg=(a<0)^(b<0);
  u64 ua=a<0?-(u64)a:(u64)a; u64 ub=b<0?-(u64)b:(u64)b;
  u64 a_lo=ua&0xFFFFFFFFULL; u64 a_hi=ua>>32;
  u64 b_lo=ub&0xFFFFFFFFULL; u64 b_hi=ub>>32;
  u64 lo_lo=a_lo*b_lo; u64 hi_lo=a_hi*b_lo; u64 lo_hi=a_lo*b_hi; u64 hi_hi=a_hi*b_hi;
  u64 mid=(lo_lo>>32)+(hi_lo&0xFFFFFFFFULL)+(lo_hi&0xFFFFFFFFULL);
  u64 res_hi=hi_hi+(hi_lo>>32)+(lo_hi>>32)+(mid>>32);
  u64 res=(res_hi<<32)|(mid&0xFFFFFFFFULL);
  return neg?-(s64)res:(s64)res;
}
s64 q32_div_c(s64 a, s64 b){
  if(b==0) return 0;
  int neg=(a<0)^(b<0);
  u64 ua=a<0?-(u64)a:(u64)a; u64 ub=b<0?-(u64)b:(u64)b;
  u64 q=div64_c(ua<<16, ub); // approx Q32
  q<<=16;
  return neg?-(s64)q:(s64)q;
}
s64 q32_sin_q32_c(s64 ang_q32){ u64 u=(u64)ang_q32; u=(u*256)>>32; return (s64)q32_sin_table[u&0xFF]; }
